def climbStairs(n):
    @lru_cache(None)
    def dfs(step):
        if step <= 1:
            return 1
        return dfs(step - 1) + dfs(step - 2)
    return dfs(n)

def coinChange(coins, amount):
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for total in range(1, amount + 1):
        for coin in coins:
            if coin <= total:
                dp[total] = min(dp[total], dp[total - coin] + 1)
    return dp[amount] if dp[amount] != amount + 1 else -1

