def coinChange(coins, amount):
    @lru_cache(None)
    def dfs(rem):
        if rem == 0:
            return 0
        if rem < 0:
            return float('inf')
        best = min(dfs(rem - coin) + 1 for coin in coins)
        return best
    answer = dfs(amount)
    return answer if answer != float('inf') else -1

